  if (!W.some(t => segRect(a.x, a.y, b.x, b.y, t))) return d;
  const key = Math.round(a.x * 20) + ',' + Math.round(a.y * 20) + ',' + Math.round(b.x * 20) + ',' + Math.round(b.y * 20); let L = TWC.cache.get(key);
