function tyRects(f, fi) { const [k, X, Y, a, b, ang, hz] = f, th = ang * Math.PI / 180, c = Math.cos(th), sn = Math.sin(th), R = Math.max(a, b), C = 0.25, out = []; for (let y = Y - R; y < Y + R; y += C) { const ym = y + C / 2; let x0 = null, x1 = null; for (let x = X - R; x <= X + R; x += 0.05) { const dx = x - X, dy = ym - Y, u = dx * c + dy * sn, v = -dx * sn + dy * c; if ((u / a) ** 2 + (v / b) ** 2 <= 1) { if (x0 === null) x0 = x; x1 = x; } } if (x0 !== null) out.push({ x: x0, y, w: x1 - x0 + 0.05, h: C, t: (k === 'O' || k === 'P') ? 'wall' : 'cover', hz, ty: fi }); } return out; }
export const MAPNAMES = [...Array(8).keys()].map(i => 'Gallowdark ' + (i + 1)).concat(OPEN.map(m => m.n));
