export function pieceRect(p) {
  const k = p[0], sx = Math.abs(p[4]), sz = Math.abs(p[6]);
  let lx, lz; if (k === 0) { lx = .96 * sx; lz = 1.03 * sz; } else if (k === 3) { lx = .6; lz = sz; } else { lx = 3.8 * sx; lz = .35; }
  if ((((p[3] % 180) + 180) % 180) === 90) { const t = lx; lx = lz; lz = t; }
  const c = CQPOS(p); return { x: c.x - lx / 2, y: c.y - lz / 2, w: lx, h: lz, t: 'wall' };
}
